#include <stdint.h>

#define RCC_BASE 0x40021000
#define RCC_APB2ENR *(volatile uint32_t *)(RCC_BASE + 0x18)
#define GPIOA_BASE 0x40010800
#define GPIOA_CRH *(volatile uint32_t *)(GPIOA_BASE + 0x04)
#define GPIOA_ODR *(volatile uint32_t *)(GPIOA_BASE + 0x0C)
#define AFIO_BASE 0x40010000
#define AFIO_EXTICR1 *(volatile uint32_t *)(AFIO_BASE + 0x0C)
#define EXTI_BASE 0x40010400
#define EXTI_IMR *(volatile uint32_t *)(EXTI_BASE + 0x0)
#define EXTI_RTSR *(volatile uint32_t *)(EXTI_BASE + 0x8)
#define EXTI_PR *(volatile uint32_t *)(EXTI_BASE + 0x14)
#define NVIC_BASE 0xE000E100
#define NVIC_ISER0 *(volatile uint32_t *)(NVIC_BASE + 0x00)


void clockInit(void){
	//Enabling AFIO and IOPA
	RCC_APB2ENR |= (0x5 << 0);
}

void gpioInit(void){
	//Setting pin 13 port as output
	GPIOA_CRH &= (0x0 << 20);
	GPIOA_CRH |= (0x1 << 20);
}

void interruptInit (void){
	//Mapping pin 0 port A to EXTI0
	AFIO_EXTICR1 |= (0x0 << 0);
	//Writing a ‘1’ to the corresponding bit in the interrupt mask register
	EXTI_IMR |= (1 << 0);
	// Rising trigger enabled
	EXTI_RTSR |= (1 << 0);

	NVIC_ISER0 |= (1 << 6);

}


int main(void)
{
	clockInit();
	gpioInit();
    interruptInit ();
    /* Loop forever */
	for(;;);
}

void EXTI0_IRQHandler(){
	GPIOA_ODR ^= (1 << 13);
	EXTI_PR |= (1 << 0);
}
